<?php require 'app.php';need_school(['director']);$sid=school_id();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$roleKey=$_POST['role_key'];if(!in_array($roleKey,['dos','patron','matron'],true))throw new RuntimeException('Choose a valid staff role.');$pw=$_POST['password'];if(strlen($pw)<10)throw new RuntimeException('Password must contain at least 10 characters.');$pdo=db();$pdo->beginTransaction();$email=strtolower(trim($_POST['email']));$existing=$pdo->prepare('SELECT u.id,u.is_platform_owner,(SELECT count(*) FROM memberships m WHERE m.user_id=u.id AND m.school_id<>?) other_school FROM users u WHERE lower(u.email)=?');$existing->execute([$sid,$email]);$found=$existing->fetch();if($found&&($found['is_platform_owner']||((int)$found['other_school']>0)))throw new RuntimeException('This email is already used by an account in another school.');$q=$pdo->prepare('INSERT INTO users(full_name,email,password_hash) VALUES(?,?,?) ON CONFLICT(email) DO UPDATE SET full_name=EXCLUDED.full_name,password_hash=EXCLUDED.password_hash RETURNING id');$q->execute([trim($_POST['full_name']),$email,password_hash($pw,PASSWORD_DEFAULT)]);$uid=(int)$q->fetchColumn();$q=$pdo->prepare('INSERT INTO memberships(school_id,user_id,role_key) VALUES(?,?,?) ON CONFLICT(school_id,user_id) DO UPDATE SET role_key=EXCLUDED.role_key,status=\'active\'');$q->execute([$sid,$uid,$roleKey]);$pdo->prepare('DELETE FROM class_assignments WHERE school_id=? AND user_id=?')->execute([$sid,$uid]);foreach(($_POST['classes']??[]) as $cid){$q=$pdo->prepare('INSERT INTO class_assignments(school_id,class_id,user_id) SELECT ?,id,? FROM classes WHERE id=? AND school_id=? ON CONFLICT DO NOTHING');$q->execute([$sid,$uid,(int)$cid,$sid]);}$pdo->commit();$msg='Staff account saved.';}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$msg=$e->getMessage();}}$q=db()->prepare('SELECT u.full_name,u.email,m.role_key,u.status FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.school_id=? ORDER BY m.role_key,u.full_name');$q->execute([$sid]);$staff=$q->fetchAll();$q=db()->prepare('SELECT id,name,stream FROM classes WHERE school_id=? ORDER BY name,stream');$q->execute([$sid]);$classes=$q->fetchAll();ob_start();?><div class="panel"><h2>Create or update staff</h2><?php if($msg):?><p><?=h($msg)?></p><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><div class="grid"><label>Full name<input name="full_name" required></label><label>Email<input name="email" type="email" required></label><label>Temporary password (10+ chars)<input name="password" minlength="10" required></label><label>Role<select name="role_key"><option value="dos">DOS</option><option value="patron">Patron</option><option value="matron">Matron</option></select></label></div><p>Assign classes (required for Patron and Matron):</p><?php foreach($classes as $c):?><label style="display:inline-block;width:auto;margin-right:16px"><input style="width:auto" type="checkbox" name="classes[]" value="<?=$c['id']?>"> <?=h($c['name'].' '.$c['stream'])?></label><?php endforeach;?><p><button>Save staff account</button></p></form></div><div class="panel"><h2>School staff</h2><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th></tr><?php foreach($staff as $x):?><tr><td><?=h($x['full_name'])?></td><td><?=h($x['email'])?></td><td><?=h(strtoupper($x['role_key']))?></td><td><?=h($x['status'])?></td></tr><?php endforeach;?></table></div><?php page('Staff Management',ob_get_clean());
